const supaUrl = 'https://tidngxclgaspltzqoemi.supabase.co';
const supaKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InRpZG5neGNsZ2FzcGx0enFvZW1pIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODI5MjA0NTUsImV4cCI6MjA5ODQ5NjQ1NX0.RXKWEePM6xsmXgd1ZVgkgavegQTNAIw-9FkMh-7vfFE';
const headers = { 'apikey': supaKey, 'Authorization': 'Bearer ' + supaKey };

const hoje = new Date();
const hojeStr = hoje.toISOString().split('T')[0];
const diasNomes = ['Domingo', 'Segunda', 'Terca', 'Quarta', 'Quinta', 'Sexta', 'Sabado'];
const diaNome = diasNomes[hoje.getDay()];

// Buscar tarefas criadas hoje
const tarefasResp = await fetch(`${supaUrl}/rest/v1/tarefas?created_at=gte.${hojeStr}T00:00:00&created_at=lt.${hojeStr}T23:59:59&select=id,comando_original,propriedade_id,setores(nome),colaboradores:responsavel_id(nome)&order=propriedade_id`, { headers });
const tarefas = await tarefasResp.json();

if (!tarefas || tarefas.length === 0) {
  return [{ json: { skip: true } }];
}

// Buscar checklist_items de hoje
const itemsResp = await fetch(`${supaUrl}/rest/v1/checklist_items?created_at=gte.${hojeStr}T00:00:00&created_at=lt.${hojeStr}T23:59:59&select=id,descricao,colaborador_id,tarefa_id,colaboradores:colaborador_id(nome)&order=ordem`, { headers });
const items = await itemsResp.json();

// Agrupar por propriedade
const props = {
  '229e2813-6d46-4bdb-9aee-5d9a119733e6': { nome: 'Sitio Labareda', chatId: '-1003848664476', isLabareda: true, tarefas: [], items: [] },
  '4a5580bb-9971-40c9-9409-ffbe0cff65da': { nome: 'Sitio Sao Miguel', chatId: '-5579671663', isLabareda: false, tarefas: [], items: [] },
};

for (const t of tarefas) {
  if (props[t.propriedade_id]) props[t.propriedade_id].tarefas.push(t);
}
for (const i of (items || [])) {
  // Encontrar propriedade pelo tarefa_id
  for (const t of tarefas) {
    if (t.id === i.tarefa_id && props[t.propriedade_id]) {
      props[t.propriedade_id].items.push(i);
      break;
    }
  }
}

const results = [];
for (const [propId, prop] of Object.entries(props)) {
  if (prop.tarefas.length === 0) continue;

  let msg = `\ud83c\udf05 Bom dia! Tarefas de ${diaNome} (${hojeStr.split('-').reverse().join('/')})\n\n`;
  msg += `\ud83c\udfe1 ${prop.nome}\n`;
  msg += `\ud83d\udccb ${prop.tarefas.length} tarefa(s) | ${prop.items.length} item(ns)\n\n`;

  for (const t of prop.tarefas) {
    const setor = t.setores ? t.setores.nome : '';
    const resp = t.colaboradores ? t.colaboradores.nome : '';
    msg += `\ud83d\udccc ${t.comando_original}`;
    if (setor) msg += ` (${setor})`;
    if (resp) msg += ` — ${resp}`;
    msg += '\n';

    // Listar items desta tarefa
    const tarefaItems = prop.items.filter(i => i.tarefa_id === t.id);
    for (const item of tarefaItems) {
      const colabNome = item.colaboradores ? item.colaboradores.nome : '';
      msg += `   \u25cb ${item.descricao}`;
      if (colabNome) msg += ` (${colabNome})`;
      msg += '\n';
    }
    msg += '\n';
  }

  msg += '\ud83d\udcf1 Acesse o painel para marcar as tarefas!';

  results.push({ json: { mensagem: msg, chatId: prop.chatId, isLabareda: prop.isLabareda, propriedade: prop.nome } });
}

if (results.length === 0) return [{ json: { skip: true } }];
return results;
